#![allow(
    tigerstyle::raw_arithmetic_overflow,
    tigerstyle::unbounded_collection_growth,
    reason = "Owner: noble-maintainers; this differential harness parses a frozen corpus of a few hundred short graphs and indexes node vectors it built from that corpus, so growth and index arithmetic are bounded by the corpus."
)]
//! Finite comparison of `grad::forward` and `grad::backward` for `f32` against the ordered binary32
//! reference `NobleFoundation.ReverseAD.Ordered` (issue #45).
//!
//! `grad_ordered/corpus.txt` is generated by `verification/foundation/grad-ordered/corpus.lean` from
//! the Lean model alone, so every expected forward value and gradient is independent of the
//! implementation under test. Each graph is built with the IR builder, checked, and run through the
//! real forward and reverse passes; every node is compared bit for bit, with all NaN encodings one
//! observation class, as in the binary32 model.
//!
//! The comparison is finite and differential, not a refinement proof. The seeded faults are
//! test-local re-implementations of the reverse pass, fed only the corpus's reference forward values,
//! with one ordering or initialization rule changed. The unmutated re-implementation must reproduce
//! every expectation, and each fault must disagree with at least one, so the corpus discriminates
//! those rules rather than agreeing with anything.

use noble_ngraph::check::CheckedGraph;
use noble_ngraph::grad::{self, DerivOptions};
use noble_ngraph::ir::{GraphBuilder, Literal, NodeId, Op, ScalarType, SubProfile, Subject};

/// One corpus node: its tag (`i`, `p`, `c`, `a`, `s` or `m`) and up to two fields, a slot
/// number, constant bits or two operand node indices.
#[derive(Clone, Copy, Debug)]
struct Node {
    tag: char,
    first: u32,
    second: u32,
}

impl Node {
    /// Whether the node is an addition, subtraction or multiplication.
    fn is_binary(self) -> bool {
        matches!(self.tag, 'a' | 's' | 'm')
    }
}

/// A corpus index as a vector position.
fn at(index: u32) -> usize {
    usize::try_from(index).expect("corpus index fits usize")
}

struct Case {
    name: String,
    nodes: Vec<Node>,
    slots: Vec<u32>,
    seeds: Vec<(u32, u32)>,
    values: Vec<u32>,
    grads: Vec<u32>,
}

fn encoding(field: &str, line: usize) -> u32 {
    u32::from_str_radix(field, 16)
        .unwrap_or_else(|_| panic!("corpus line {line}: not a binary32 encoding: {field}"))
}

fn index(field: &str, line: usize) -> u32 {
    field
        .parse::<u32>()
        .unwrap_or_else(|_| panic!("corpus line {line}: not a node or slot index: {field}"))
}

fn operands(field: &str, line: usize) -> (u32, u32) {
    let (a, b) = field
        .split_once('.')
        .unwrap_or_else(|| panic!("corpus line {line}: not an operand pair: {field}"));
    (index(a, line), index(b, line))
}

fn node(field: &str, line: usize) -> Node {
    let mut characters = field.chars();
    let tag = characters
        .next()
        .unwrap_or_else(|| panic!("corpus line {line}: empty node"));
    let rest = characters.as_str();
    let (first, second) = match tag {
        'i' | 'p' => (index(rest, line), 0),
        'c' => (encoding(rest, line), 0),
        'a' | 's' | 'm' => operands(rest, line),
        _ => panic!("corpus line {line}: unknown node {field}"),
    };
    Node { tag, first, second }
}

fn encodings(field: &str, line: usize) -> Vec<u32> {
    if field.is_empty() {
        return Vec::new();
    }
    field.split(',').map(|item| encoding(item, line)).collect()
}

fn corpus() -> Vec<Case> {
    let text = include_str!("corpus.txt");
    let declared = text
        .lines()
        .next()
        .and_then(|header| header.strip_prefix("# cases: "))
        .map(|count| index(count, 0))
        .unwrap_or_else(|| panic!("corpus header declares its case count"));
    let mut cases = Vec::new();
    for (line, row) in text.lines().enumerate() {
        if row.starts_with('#') || row.trim().is_empty() {
            continue;
        }
        let fields: Vec<&str> = row.split(' ').collect();
        assert_eq!(fields.len(), 6, "corpus line {line} has six fields: {row}");
        let field = |position: usize, key: &str| {
            fields[position]
                .strip_prefix(key)
                .and_then(|rest| rest.strip_prefix('='))
                .unwrap_or_else(|| {
                    panic!("corpus line {line}: field {position} is not {key}=: {row}")
                })
        };
        let seeds = field(3, "seeds")
            .split(',')
            .map(|item| {
                let (output, seed) = item
                    .split_once(':')
                    .unwrap_or_else(|| panic!("corpus line {line}: not an output seed: {item}"));
                (index(output, line), encoding(seed, line))
            })
            .collect();
        cases.push(Case {
            name: fields[0].to_owned(),
            nodes: field(1, "nodes")
                .split(';')
                .map(|item| node(item, line))
                .collect(),
            slots: encodings(field(2, "slots"), line),
            seeds,
            values: encodings(field(4, "values"), line),
            grads: encodings(field(5, "grads"), line),
        });
    }
    assert_eq!(
        cases.len(),
        at(declared),
        "the corpus header counts its cases"
    );
    cases
}

/// Builds and checks one corpus graph; slots are numbered in node order, as the builder numbers them.
fn build(case: &Case) -> CheckedGraph {
    let mut builder = GraphBuilder::new(
        SubProfile::F32,
        Subject::authored(&super::common::IDS, &case.name),
    );
    let mut next_slot = 0;
    for (position, node) in case.nodes.iter().enumerate() {
        let (a, b) = (NodeId(node.first), NodeId(node.second));
        let id = match node.tag {
            'i' | 'p' => {
                assert_eq!(
                    node.first, next_slot,
                    "{}: slot numbers follow node order",
                    case.name
                );
                next_slot += 1;
                if node.tag == 'i' {
                    builder.input(ScalarType::F32)
                } else {
                    builder.param()
                }
            }
            'c' => builder.constant(Literal::F32(node.first)),
            'a' => builder.op(Op::F32Add(a, b)),
            's' => builder.op(Op::F32Sub(a, b)),
            'm' => builder.op(Op::F32Mul(a, b)),
            other => panic!("{}: unknown node tag {other}", case.name),
        };
        assert_eq!(
            id.index(),
            position,
            "{}: node {position} keeps its corpus index",
            case.name
        );
    }
    for &(output, _) in &case.seeds {
        builder.output(NodeId(output));
    }
    super::common::checked(builder.finish())
}

/// Bitwise equality, with every NaN encoding one observation class.
fn same(actual: f32, expected: u32) -> bool {
    actual.to_bits() == expected || (actual.is_nan() && f32::from_bits(expected).is_nan())
}

fn compare(case: &Case, what: &str, actual: &[f32], expected: &[u32]) {
    assert_eq!(actual.len(), expected.len(), "{}: {what} count", case.name);
    for (position, (&got, &want)) in actual.iter().zip(expected).enumerate() {
        assert!(
            same(got, want),
            "{}: {what} of node {position}: rust {:08x}, reference {want:08x}",
            case.name,
            got.to_bits()
        );
    }
}

#[test]
fn forward_and_backward_match_the_lean_reference() {
    let cases = corpus();
    let mut values_compared = 0;
    let mut grads_compared = 0;
    let mut nonfinite = 0;
    let mut repeated_operand = 0;
    for case in &cases {
        let checked = build(case);
        let slots: Vec<f32> = case
            .slots
            .iter()
            .map(|&bits| f32::from_bits(bits))
            .collect();
        let values = grad::forward(&checked, &slots);
        compare(case, "forward value", &values, &case.values);
        let seeds: Vec<f32> = case
            .seeds
            .iter()
            .map(|&(_, seed)| f32::from_bits(seed))
            .collect();
        let grads = grad::backward(&checked, &values, &seeds, &DerivOptions::default());
        compare(case, "gradient", &grads, &case.grads);
        values_compared += values.len();
        grads_compared += grads.len();
        if case
            .values
            .iter()
            .chain(&case.grads)
            .any(|&bits| !f32::from_bits(bits).is_finite())
        {
            nonfinite += 1;
        }
        if case
            .nodes
            .iter()
            .any(|node| node.is_binary() && node.first == node.second)
        {
            repeated_operand += 1;
        }
    }
    println!(
        "grad-ordered-differential cases={} values={values_compared} grads={grads_compared} nonfinite={nonfinite} repeated-operand={repeated_operand}",
        cases.len()
    );
}

/// One changed rule of the reverse pass.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Fault {
    None,
    AscendingTraversal,
    OverwriteAccumulation,
    PresummedRepeatedOperand,
    AssignedSeed,
    SubtractionSign,
    MultiplicationOwnValue,
    FusedMultiplyAdd,
}

/// The ordered reverse pass over the reference forward values, with `fault` applied.
fn simulate(case: &Case, fault: Fault) -> Vec<f32> {
    let values: Vec<f32> = case
        .values
        .iter()
        .map(|&bits| f32::from_bits(bits))
        .collect();
    let mut gr = vec![0.0_f32; case.nodes.len()];
    for &(output, seed) in &case.seeds {
        let target = at(output);
        let seed = f32::from_bits(seed);
        gr[target] = if fault == Fault::AssignedSeed {
            seed
        } else {
            gr[target] + seed
        };
    }
    let order: Vec<usize> = if fault == Fault::AscendingTraversal {
        (0..case.nodes.len()).collect()
    } else {
        (0..case.nodes.len()).rev().collect()
    };
    let accumulate = |gr: &mut Vec<f32>, target: u32, contribution: f32| {
        let target = at(target);
        gr[target] = if fault == Fault::OverwriteAccumulation {
            contribution
        } else {
            gr[target] + contribution
        };
    };
    for position in order {
        let gn = gr[position];
        let node = case.nodes[position];
        let (a, b) = (node.first, node.second);
        match node.tag {
            'a' => {
                accumulate(&mut gr, a, gn);
                accumulate(&mut gr, b, gn);
            }
            's' => {
                accumulate(&mut gr, a, gn);
                let negated = if fault == Fault::SubtractionSign {
                    gn
                } else {
                    0.0 - gn
                };
                accumulate(&mut gr, b, negated);
            }
            'm' => {
                let (va, vb) = (values[at(a)], values[at(b)]);
                match fault {
                    Fault::PresummedRepeatedOperand if a == b => {
                        accumulate(&mut gr, a, gn * vb + gn * va);
                    }
                    Fault::MultiplicationOwnValue => {
                        accumulate(&mut gr, a, gn * va);
                        accumulate(&mut gr, b, gn * vb);
                    }
                    Fault::FusedMultiplyAdd => {
                        gr[at(a)] = gn.mul_add(vb, gr[at(a)]);
                        gr[at(b)] = gn.mul_add(va, gr[at(b)]);
                    }
                    _ => {
                        accumulate(&mut gr, a, gn * vb);
                        accumulate(&mut gr, b, gn * va);
                    }
                }
            }
            _ => {}
        }
    }
    gr
}

#[test]
fn corpus_detects_each_seeded_fault() {
    let cases = corpus();
    let faults = [
        Fault::AscendingTraversal,
        Fault::OverwriteAccumulation,
        Fault::PresummedRepeatedOperand,
        Fault::AssignedSeed,
        Fault::SubtractionSign,
        Fault::MultiplicationOwnValue,
        Fault::FusedMultiplyAdd,
    ];
    let mut caught = [0_usize; 7];
    for case in &cases {
        compare(
            case,
            "unmutated simulation",
            &simulate(case, Fault::None),
            &case.grads,
        );
        for (slot, &fault) in faults.iter().enumerate() {
            let mutated = simulate(case, fault);
            if mutated
                .iter()
                .zip(&case.grads)
                .any(|(&got, &want)| !same(got, want))
            {
                caught[slot] += 1;
            }
        }
    }
    let report: Vec<String> = faults
        .iter()
        .zip(caught)
        .map(|(fault, count)| format!("{fault:?}={count}"))
        .collect();
    println!(
        "grad-ordered-mutations cases={} {}",
        cases.len(),
        report.join(" ")
    );
    for (fault, count) in faults.iter().zip(caught) {
        assert!(count > 0, "the corpus does not detect {fault:?}");
    }
}
